-- =====================================================================
-- 06c KEYS: primary keys (technical) and unique keys (business keys) on the tables.
--   Snowflake does not enforce them, but they are real metadata: BI tools, semantic views and the
--   Knowledge Fabric read them (SHOW PRIMARY KEYS / SHOW UNIQUE KEYS). Views get a KEY_ROLE tag instead.
--   (run.py treats a failing statement here as a warning, e.g. when a key already exists on a re-run)
-- =====================================================================
USE WAREHOUSE {{WAREHOUSE}};
ALTER TABLE {{DATABASE}}.{{LANDING}}.SAP_T001  ADD CONSTRAINT PK_SAP_T001  PRIMARY KEY (BUKRS);
ALTER TABLE {{DATABASE}}.{{LANDING}}.SAP_T005T ADD CONSTRAINT PK_SAP_T005T PRIMARY KEY (SPRAS, LAND1);
ALTER TABLE {{DATABASE}}.{{LANDING}}.SAP_LFA1  ADD CONSTRAINT PK_SAP_LFA1  PRIMARY KEY (LIFNR);
ALTER TABLE {{DATABASE}}.{{LANDING}}.SAP_LFB1  ADD CONSTRAINT PK_SAP_LFB1  PRIMARY KEY (LIFNR, BUKRS);
ALTER TABLE {{DATABASE}}.{{LANDING}}.SAP_LFBK  ADD CONSTRAINT PK_SAP_LFBK  PRIMARY KEY (LIFNR);
ALTER TABLE {{DATABASE}}.{{LANDING}}.SAP_BKPF  ADD CONSTRAINT PK_SAP_BKPF  PRIMARY KEY (BUKRS, BELNR, GJAHR);
ALTER TABLE {{DATABASE}}.{{LANDING}}.SAP_BSEG  ADD CONSTRAINT PK_SAP_BSEG  PRIMARY KEY (BUKRS, BELNR, GJAHR, BUZEI);
ALTER TABLE {{DATABASE}}.{{LANDING}}.SAP_BSEC  ADD CONSTRAINT PK_SAP_BSEC  PRIMARY KEY (BUKRS, BELNR, GJAHR, BUZEI);

ALTER TABLE {{DATABASE}}.{{EDW}}.DIM_COMPANY_CODE ADD CONSTRAINT PK_DIM_COMPANY_CODE PRIMARY KEY (COMPANY_CODE);
ALTER TABLE {{DATABASE}}.{{EDW}}.DIM_VENDOR       ADD CONSTRAINT PK_DIM_VENDOR PRIMARY KEY (VENDOR_ID);
ALTER TABLE {{DATABASE}}.{{EDW}}.FACT_ACCOUNTS_PAYABLE_GLOBAL ADD CONSTRAINT PK_FACT_AP PRIMARY KEY (AP_LINE_ID);
ALTER TABLE {{DATABASE}}.{{EDW}}.FACT_ACCOUNTS_PAYABLE_GLOBAL ADD CONSTRAINT BK_FACT_AP UNIQUE (COMPANY_CODE, DOCUMENT_NUMBER, FISCAL_YEAR, LINE_ITEM);
ALTER TABLE {{DATABASE}}.{{EDW}}.FACT_ACCOUNTS_PAYABLE_GLOBAL ADD CONSTRAINT FK_FACT_AP_VENDOR FOREIGN KEY (VENDOR_ID) REFERENCES {{DATABASE}}.{{EDW}}.DIM_VENDOR (VENDOR_ID);
ALTER TABLE {{DATABASE}}.{{EDW}}.FACT_ACCOUNTS_PAYABLE_GLOBAL ADD CONSTRAINT FK_FACT_AP_COMPANY FOREIGN KEY (COMPANY_CODE) REFERENCES {{DATABASE}}.{{EDW}}.DIM_COMPANY_CODE (COMPANY_CODE);

ALTER TABLE {{DATABASE}}.{{DATAMART}}.AP_AGING_BUCKETS ADD CONSTRAINT PK_AP_AGING_BUCKETS PRIMARY KEY (BUCKET_ORDER);
ALTER TABLE {{DATABASE}}.{{DATAMART}}.AP_AGING_BUCKETS ADD CONSTRAINT BK_AP_AGING_BUCKETS UNIQUE (BUCKET_NAME);
ALTER TABLE {{DATABASE}}.{{DATAMART}}.DM_AP_OPEN_ITEMS ADD CONSTRAINT PK_DM_AP_OPEN_ITEMS PRIMARY KEY (AP_LINE_ID);
ALTER TABLE {{DATABASE}}.{{DATAMART}}.DM_AP_OPEN_ITEMS ADD CONSTRAINT BK_DM_AP_OPEN_ITEMS UNIQUE (COMPANY_CODE, DOCUMENT_NUMBER);
ALTER TABLE {{DATABASE}}.{{DATAMART}}.DM_AP_AGING_SUMMARY ADD CONSTRAINT BK_DM_AP_AGING_SUMMARY UNIQUE (AS_OF_DATE, COMPANY_CODE, VENDOR_COUNTRY_NAME, AGING_BUCKET);
ALTER TABLE {{DATABASE}}.{{DATAMART}}.DM_AP_VENDOR ADD CONSTRAINT PK_DM_AP_VENDOR PRIMARY KEY (VENDOR_ID);

-- Views cannot carry constraints: their keys are tagged
ALTER VIEW {{DATABASE}}.{{REPORTING}}.VW_AP_OPEN_ITEMS MODIFY COLUMN COMPANY_CODE SET TAG {{DATABASE}}.{{GOVERNANCE}}.KEY_ROLE = 'Business key';
ALTER VIEW {{DATABASE}}.{{REPORTING}}.VW_AP_OPEN_ITEMS MODIFY COLUMN DOCUMENT_NUMBER SET TAG {{DATABASE}}.{{GOVERNANCE}}.KEY_ROLE = 'Business key';
ALTER VIEW {{DATABASE}}.{{REPORTING}}.VW_AP_OVERDUE_ITEMS MODIFY COLUMN COMPANY_CODE SET TAG {{DATABASE}}.{{GOVERNANCE}}.KEY_ROLE = 'Business key';
ALTER VIEW {{DATABASE}}.{{REPORTING}}.VW_AP_OVERDUE_ITEMS MODIFY COLUMN DOCUMENT_NUMBER SET TAG {{DATABASE}}.{{GOVERNANCE}}.KEY_ROLE = 'Business key';
ALTER VIEW {{DATABASE}}.{{REPORTING}}.VW_AP_AGING_SUMMARY MODIFY COLUMN AS_OF_DATE SET TAG {{DATABASE}}.{{GOVERNANCE}}.KEY_ROLE = 'Business key';
ALTER VIEW {{DATABASE}}.{{REPORTING}}.VW_AP_AGING_SUMMARY MODIFY COLUMN COMPANY_CODE SET TAG {{DATABASE}}.{{GOVERNANCE}}.KEY_ROLE = 'Business key';
ALTER VIEW {{DATABASE}}.{{REPORTING}}.VW_AP_AGING_SUMMARY MODIFY COLUMN VENDOR_COUNTRY SET TAG {{DATABASE}}.{{GOVERNANCE}}.KEY_ROLE = 'Business key';
ALTER VIEW {{DATABASE}}.{{REPORTING}}.VW_AP_AGING_SUMMARY MODIFY COLUMN AGING_BUCKET SET TAG {{DATABASE}}.{{GOVERNANCE}}.KEY_ROLE = 'Business key';
ALTER VIEW {{DATABASE}}.{{REPORTING}}.VW_AP_VENDOR MODIFY COLUMN VENDOR_ID SET TAG {{DATABASE}}.{{GOVERNANCE}}.KEY_ROLE = 'Primary key';
